// ---------------------------------------------------------------------------
// Single Round (Frozen) — STYLE reference image.
//
// 2026-10-22. "neden referanstakinin exactly same yapamiyorsun?" The round's
// garland is already that photo replayed balloon for balloon in the layout
// guide, but the room, the daylight, the balloons' finish and the flat cut
// lettering are things words kept missing. The photo itself is handed to the
// model as IMAGE 2 (the flux-2 edit models take several image_urls): image 1
// — the guide — still fixes where everything stands; image 2 shows how it all
// looks. Tested on three seeds: room, light, fullness and lettering matched
// the photo, and the plinth held on all three once the opening sentence named
// it. Frozen only — the photo is a Frozen palette, and its blue and lilac would
// bleed into any other.
//
// The customer's reference photo, 720px wide, as a JPEG data URI.
export const ROUND_STYLE_REFERENCE: string =
  "data:image/jpeg;base64,";

/** Whether a scene is shot against the round style reference: a lone round, Frozen, with balloons. */
export function usesRoundStyleReference(scene: { theme?: string; panels: { type: string }[]; balloons?: { style?: string } }): boolean {
  return scene.panels.length === 1 && scene.panels[0]?.type === "round"
    && String(scene.theme ?? "").toLowerCase() === "frozen" && (scene.balloons?.style ?? "none") !== "none";
}
